import '../models/models.dart';

class AnnualHistoryCivicsUnit {
  final SchoolLevel level;
  final String code, domain, title, lessonId, lessonTitle, summary, content;
  final int unitOrder;
  final List<String> keyPoints;
  final List<Exercise> exercises;
  const AnnualHistoryCivicsUnit({
    required this.level, required this.code, required this.domain,
    required this.unitOrder, required this.title, required this.lessonId,
    required this.lessonTitle, required this.summary, required this.content,
    required this.keyPoints, required this.exercises,
  });
  String get subjectId => 'core_${domain}_$code';
  String get chapterId => 'core_${domain}_${code}_unit_$unitOrder';
}

const annualHistoryCivicsUnits = <AnnualHistoryCivicsUnit>[
  AnnualHistoryCivicsUnit(level:SchoolLevel.cinquieme,code:'5e',domain:'hg',unitOrder:1,title:'Les grands royaumes d’Afrique de l’Ouest',lessonId:'core_hg_5e_kingdoms',lessonTitle:'Ghana, Mali et Songhaï : des royaumes organisés',summary:'Découvrir l’organisation et les échanges des grands royaumes ouest-africains.',content:'L’Afrique de l’Ouest a connu de puissants royaumes et empires. Le Ghana ancien, l’empire du Mali et l’empire Songhaï ont développé l’agriculture, l’artisanat, le commerce et des pouvoirs politiques organisés. Les échanges transsahariens reliaient notamment les régions productrices d’or aux routes du sel. Les villes, les marchés et les centres d’enseignement participaient à leur rayonnement. Pour étudier un royaume, on situe son territoire, ses dirigeants, ses activités et ses échanges.',keyPoints:['Ghana, Mali et Songhaï sont des royaumes/empire ouest-africains','Les échanges transsahariens reliaient différentes régions','Étudier territoire, pouvoir, activités et commerce'],exercises:[
    Exercise(id:'core_hg_5e_kg1',lessonId:'core_hg_5e_kingdoms',question:'Quel empire ouest-africain est associé à Mansa Moussa ?',options:['Mali','Rome','Ming'],correctIndex:0,explanation:'Mansa Moussa est un souverain célèbre de l’empire du Mali.'),
    Exercise(id:'core_hg_5e_kg2',lessonId:'core_hg_5e_kingdoms',question:'Quel produit était échangé sur les routes transsahariennes ?',options:['Le sel','Le pétrole raffiné','Les téléphones'],correctIndex:0,explanation:'Le sel et l’or faisaient partie des produits majeurs du commerce transsaharien.'),
    Exercise(id:'core_hg_5e_kg3',lessonId:'core_hg_5e_kingdoms',question:'Pour étudier un royaume, il faut notamment repérer…',options:['Son territoire et ses activités','Seulement la couleur de son drapeau','Uniquement sa météo actuelle'],correctIndex:0,explanation:'Le territoire, le pouvoir, les activités et les échanges permettent de comprendre un royaume.'),
  ]),
  AnnualHistoryCivicsUnit(level:SchoolLevel.cinquieme,code:'5e',domain:'hg',unitOrder:2,title:'Se repérer sur une carte de l’Afrique',lessonId:'core_hg_5e_map_africa',lessonTitle:'Lire une carte et situer le Togo',summary:'Utiliser les repères géographiques, la légende et l’échelle.',content:'Une carte représente un espace à une échelle réduite. Le titre indique le sujet, la légende explique les symboles, l’orientation permet de repérer le nord et l’échelle aide à estimer les distances. Le Togo se situe en Afrique de l’Ouest, au bord du golfe de Guinée. Pour localiser un lieu, utilise les pays voisins, les océans, les lignes de latitude et de longitude et les repères de la carte.',keyPoints:['Lire le titre, la légende et l’orientation','Le Togo se trouve en Afrique de l’Ouest','L’échelle représente la réduction des distances'],exercises:[
    Exercise(id:'core_hg_5e_mp1',lessonId:'core_hg_5e_map_africa',question:'Dans quelle région d’Afrique se trouve le Togo ?',options:['Afrique de l’Ouest','Afrique australe','Afrique orientale'],correctIndex:0,explanation:'Le Togo est situé en Afrique de l’Ouest.'),
    Exercise(id:'core_hg_5e_mp2',lessonId:'core_hg_5e_map_africa',question:'À quoi sert la légende d’une carte ?',options:['À expliquer les symboles','À remplacer le titre','À cacher les distances'],correctIndex:0,explanation:'La légende explique la signification des couleurs et symboles.'),
    Exercise(id:'core_hg_5e_mp3',lessonId:'core_hg_5e_map_africa',question:'Quel élément permet d’estimer une distance sur la carte ?',options:['L’échelle','La légende seule','Le titre'],correctIndex:0,explanation:'L’échelle relie les distances sur la carte aux distances réelles.'),
  ]),
  AnnualHistoryCivicsUnit(level:SchoolLevel.cinquieme,code:'5e',domain:'ecm',unitOrder:1,title:'Droits et devoirs de l’enfant',lessonId:'core_ecm_5e_child_rights',lessonTitle:'Connaître les droits et les responsabilités',summary:'Identifier des droits fondamentaux et les responsabilités à l’école et en famille.',content:'Chaque enfant a droit à la protection, à l’éducation, à la santé, à un nom et au respect de sa dignité. Les droits s’accompagnent de responsabilités adaptées à l’âge : respecter les autres, suivre les règles de sécurité, prendre soin du matériel commun et demander de l’aide lorsqu’une situation est dangereuse. Aucun enfant ne doit être humilié, exploité ou discriminé.',keyPoints:['Droit à l’éducation, à la santé et à la protection','Respecter les autres et le matériel commun','Signaler une situation dangereuse à un adulte de confiance'],exercises:[
    Exercise(id:'core_ecm_5e_cr1',lessonId:'core_ecm_5e_child_rights',question:'Le droit à l’éducation signifie que l’enfant doit pouvoir…',options:['Aller à l’école et apprendre','Être privé de cours','Travailler à la place de l’école'],correctIndex:0,explanation:'L’éducation est un droit fondamental de l’enfant.'),
    Exercise(id:'core_ecm_5e_cr2',lessonId:'core_ecm_5e_child_rights',question:'Que faire si un enfant est en danger ?',options:['En parler à un adulte de confiance','Garder le secret à tout prix','Encourager le danger'],correctIndex:0,explanation:'Un adulte de confiance peut aider à protéger l’enfant.'),
    Exercise(id:'core_ecm_5e_cr3',lessonId:'core_ecm_5e_child_rights',question:'Quelle responsabilité protège la vie collective ?',options:['Respecter les autres et les règles de sécurité','Détruire le matériel','Insulter les camarades'],correctIndex:0,explanation:'Le respect des personnes et des règles aide toute la classe.'),
  ]),
  AnnualHistoryCivicsUnit(level:SchoolLevel.cinquieme,code:'5e',domain:'ecm',unitOrder:2,title:'Solidarité et environnement',lessonId:'core_ecm_5e_solidarity',lessonTitle:'Agir avec solidarité dans sa communauté',summary:'Comprendre l’entraide et les gestes de protection de l’environnement.',content:'La solidarité consiste à aider les autres et à agir ensemble pour le bien commun. À l’école et dans le quartier, elle se manifeste par l’entraide, le partage équitable et le respect des personnes. Protéger l’environnement signifie éviter le gaspillage, garder les lieux propres, trier les déchets lorsque c’est possible et préserver l’eau et les arbres. Une action collective se prépare, se répartit et s’évalue.',keyPoints:['La solidarité est l’entraide et la responsabilité partagée','Éviter le gaspillage et protéger l’eau','Organiser une action collective'],exercises:[
    Exercise(id:'core_ecm_5e_so1',lessonId:'core_ecm_5e_solidarity',question:'Quel comportement montre la solidarité ?',options:['Aider un camarade en difficulté','Se moquer de lui','Refuser toute coopération'],correctIndex:0,explanation:'Aider une personne en difficulté est un geste de solidarité.'),
    Exercise(id:'core_ecm_5e_so2',lessonId:'core_ecm_5e_solidarity',question:'Quel geste protège l’environnement ?',options:['Fermer un robinet inutilisé','Jeter les déchets dans la rue','Brûler les plastiques à l’école'],correctIndex:0,explanation:'Fermer le robinet évite le gaspillage d’eau.'),
    Exercise(id:'core_ecm_5e_so3',lessonId:'core_ecm_5e_solidarity',question:'Pour réussir un projet collectif, il faut…',options:['Répartir les tâches et coopérer','Laisser une seule personne tout faire','Ne pas planifier'],correctIndex:0,explanation:'La coopération et la répartition des tâches aident le groupe.'),
  ]),
  AnnualHistoryCivicsUnit(level:SchoolLevel.quatrieme,code:'4e',domain:'hg',unitOrder:1,title:'Expansion européenne et échanges atlantiques',lessonId:'core_hg_4e_atlantic',lessonTitle:'Comprendre les échanges atlantiques et leurs conséquences',summary:'Étudier les contacts, les échanges et les violences de la traite atlantique.',content:'À partir du XVe siècle, les voyages maritimes européens intensifient les contacts entre l’Europe, l’Afrique et les Amériques. Ces échanges transportent des marchandises, des plantes et des idées, mais ils s’accompagnent aussi de la traite atlantique et de l’esclavage, qui provoquent des souffrances humaines, des déplacements forcés et des transformations économiques et sociales. L’étude historique doit distinguer les acteurs, les causes, les faits et les conséquences, et respecter la dignité des victimes.',keyPoints:['Les contacts atlantiques s’intensifient à partir du XVe siècle','La traite atlantique est une violence et une déportation forcée','Analyser causes, acteurs et conséquences'],exercises:[
    Exercise(id:'core_hg_4e_at1',lessonId:'core_hg_4e_atlantic',question:'La traite atlantique a entraîné…',options:['La déportation forcée de millions d’Africains','Un déplacement volontaire et égal','La disparition de tout commerce'],correctIndex:0,explanation:'La traite atlantique reposait sur la capture, la vente et la déportation forcée.'),
    Exercise(id:'core_hg_4e_at2',lessonId:'core_hg_4e_atlantic',question:'Quel outil aide à analyser un événement historique ?',options:['Identifier les causes et les conséquences','Ne lire que le titre','Ignorer les acteurs'],correctIndex:0,explanation:'Les causes, acteurs et conséquences permettent d’analyser un événement.'),
    Exercise(id:'core_hg_4e_at3',lessonId:'core_hg_4e_atlantic',question:'Comment étudier la traite atlantique ?',options:['Avec rigueur et respect de la dignité humaine','En minimisant les souffrances','En inventant des faits'],correctIndex:0,explanation:'L’histoire doit être rigoureuse et respecter les victimes.'),
  ]),
  AnnualHistoryCivicsUnit(level:SchoolLevel.quatrieme,code:'4e',domain:'hg',unitOrder:2,title:'Population, villes et activités',lessonId:'core_hg_4e_population',lessonTitle:'Étudier la population et l’urbanisation',summary:'Lire des données de population et comprendre les transformations des villes.',content:'La population d’un territoire évolue avec les naissances, les décès et les migrations. L’urbanisation est l’augmentation de la part des habitants vivant en ville et l’extension des espaces urbains. Les villes concentrent des services, des emplois et des échanges, mais peuvent rencontrer des défis : accès à l’eau, logement, transport, déchets et inégalités. Un graphique ou une carte aide à comparer les territoires.',keyPoints:['Population : naissances, décès et migrations','Urbanisation : croissance des espaces urbains','Les villes offrent des services mais rencontrent des défis'],exercises:[
    Exercise(id:'core_hg_4e_po1',lessonId:'core_hg_4e_population',question:'Qu’est-ce que l’urbanisation ?',options:['La croissance des espaces et populations urbains','La baisse de toutes les villes','Le déplacement des montagnes'],correctIndex:0,explanation:'L’urbanisation correspond à la croissance des populations et espaces urbains.'),
    Exercise(id:'core_hg_4e_po2',lessonId:'core_hg_4e_population',question:'Quel facteur fait évoluer la population ?',options:['Les migrations','La couleur des bâtiments','La forme des routes'],correctIndex:0,explanation:'Les migrations modifient la population d’un territoire.'),
    Exercise(id:'core_hg_4e_po3',lessonId:'core_hg_4e_population',question:'Quel défi peut rencontrer une ville en croissance ?',options:['L’accès au logement et à l’eau','La disparition de toute activité','L’absence de besoins'],correctIndex:0,explanation:'La croissance urbaine demande des logements et des services adaptés.'),
  ]),
  AnnualHistoryCivicsUnit(level:SchoolLevel.quatrieme,code:'4e',domain:'ecm',unitOrder:1,title:'Règles, lois et institutions',lessonId:'core_ecm_4e_law',lessonTitle:'Comprendre le rôle des lois et des institutions',summary:'Distinguer règle, loi et institution et comprendre leur rôle dans la société.',content:'Une règle organise la vie d’un groupe. Une loi est une règle juridique adoptée selon les procédures prévues par l’État. Les institutions publiques exercent des fonctions définies : représenter les citoyens, élaborer les lois, les appliquer ou rendre la justice. Le respect de la loi doit s’accompagner de la protection des droits et de l’égalité devant la loi. En cas de conflit, on recherche une solution pacifique et les voies légales.',keyPoints:['La loi organise la vie collective et protège les droits','Les institutions ont des fonctions différentes','Égalité devant la loi et recours pacifiques'],exercises:[
    Exercise(id:'core_ecm_4e_lw1',lessonId:'core_ecm_4e_law',question:'À quoi sert une loi ?',options:['À organiser la société et protéger les droits','À permettre l’injustice','À remplacer toutes les institutions'],correctIndex:0,explanation:'La loi fixe des règles communes et doit protéger les droits.'),
    Exercise(id:'core_ecm_4e_lw2',lessonId:'core_ecm_4e_law',question:'Que signifie l’égalité devant la loi ?',options:['La loi s’applique à tous selon les mêmes principes','Seuls les riches respectent la loi','Chaque personne invente sa loi'],correctIndex:0,explanation:'L’égalité devant la loi signifie que chacun bénéficie des mêmes règles et protections.'),
    Exercise(id:'core_ecm_4e_lw3',lessonId:'core_ecm_4e_law',question:'Comment résoudre un conflit de façon civique ?',options:['Par le dialogue et les voies légales','Par la violence','En menaçant les autres'],correctIndex:0,explanation:'Le dialogue et les procédures légales favorisent une solution pacifique.'),
  ]),
  AnnualHistoryCivicsUnit(level:SchoolLevel.quatrieme,code:'4e',domain:'ecm',unitOrder:2,title:'Collectivité locale et participation',lessonId:'core_ecm_4e_local',lessonTitle:'Participer à la vie de sa commune',summary:'Découvrir les services locaux et les formes de participation citoyenne.',content:'La commune est une collectivité territoriale qui organise des services de proximité selon les compétences prévues par la loi. Les citoyens peuvent participer à la vie locale en s’informant, en respectant les biens publics, en proposant des projets et en prenant part aux consultations ou élections lorsqu’ils remplissent les conditions légales. Les besoins locaux peuvent concerner l’eau, l’assainissement, les routes, les marchés et l’éducation.',keyPoints:['La commune organise des services de proximité','Protéger les biens publics','Participer par l’information, le dialogue et les procédures légales'],exercises:[
    Exercise(id:'core_ecm_4e_lo1',lessonId:'core_ecm_4e_local',question:'Quel exemple relève d’un service de proximité ?',options:['L’assainissement du quartier','Une planète lointaine','Un phénomène astronomique'],correctIndex:0,explanation:'L’assainissement fait partie des besoins de proximité.'),
    Exercise(id:'core_ecm_4e_lo2',lessonId:'core_ecm_4e_local',question:'Comment protéger un bien public ?',options:['L’utiliser avec soin et ne pas le dégrader','Le casser','Le réserver à une seule personne'],correctIndex:0,explanation:'Les biens publics servent à la communauté et doivent être préservés.'),
    Exercise(id:'core_ecm_4e_lo3',lessonId:'core_ecm_4e_local',question:'La participation citoyenne commence par…',options:['S’informer et dialoguer','Refuser toute information','Détruire les équipements'],correctIndex:0,explanation:'S’informer et dialoguer sont des formes de participation.'),
  ]),
  AnnualHistoryCivicsUnit(level:SchoolLevel.troisieme,code:'3e',domain:'hg',unitOrder:1,title:'Le Togo : colonisation et indépendance',lessonId:'core_hg_3e_togo_independence',lessonTitle:'Repères sur l’histoire contemporaine du Togo',summary:'Situer la période coloniale et l’indépendance du Togo.',content:'Le territoire du Togo a connu des formes de domination coloniale et des transformations politiques, économiques et sociales. Après la Première Guerre mondiale, le territoire est administré sous mandat puis tutelle internationale. Les mouvements politiques et sociaux revendiquent progressivement l’autonomie et l’indépendance. Le Togo accède à l’indépendance le 27 avril 1960. Pour étudier cette période, on croise les dates, les acteurs, les documents et les conséquences sur la société.',keyPoints:['Mandat puis tutelle après la Première Guerre mondiale','Les revendications politiques conduisent à l’indépendance','Indépendance du Togo : 27 avril 1960'],exercises:[
    Exercise(id:'core_hg_3e_ti1',lessonId:'core_hg_3e_togo_independence',question:'À quelle date le Togo devient-il indépendant ?',options:['27 avril 1960','1er janvier 1950','15 août 1975'],correctIndex:0,explanation:'Le Togo accède à l’indépendance le 27 avril 1960.'),
    Exercise(id:'core_hg_3e_ti2',lessonId:'core_hg_3e_togo_independence',question:'Pour étudier l’histoire contemporaine, il faut…',options:['Croiser dates, acteurs et documents','Ignorer les sources','Confondre les périodes'],correctIndex:0,explanation:'Les documents et repères chronologiques permettent de vérifier les faits.'),
    Exercise(id:'core_hg_3e_ti3',lessonId:'core_hg_3e_togo_independence',question:'Après la Première Guerre mondiale, le Togo a été administré sous…',options:['Mandat puis tutelle internationale','Un gouvernement spatial','Une administration inexistante'],correctIndex:0,explanation:'Le territoire a connu un régime de mandat puis de tutelle.'),
  ]),
  AnnualHistoryCivicsUnit(level:SchoolLevel.troisieme,code:'3e',domain:'hg',unitOrder:2,title:'Développement et intégration en Afrique de l’Ouest',lessonId:'core_hg_3e_development',lessonTitle:'Comprendre les défis du développement régional',summary:'Analyser les ressources, les échanges et la coopération en Afrique de l’Ouest.',content:'Le développement vise l’amélioration durable des conditions de vie : santé, éducation, revenus, infrastructures et environnement. Les pays d’Afrique de l’Ouest disposent de ressources agricoles, minières, maritimes et humaines, mais rencontrent aussi des défis d’accès aux services, d’emploi, de transport et de protection de l’environnement. La coopération régionale, notamment au sein de la CEDEAO, favorise les échanges, la mobilité et la coordination face à des enjeux communs. Une analyse géographique relie ressources, population, activités et contraintes.',keyPoints:['Développement : conditions de vie et services','Ressources et défis sont répartis de façon inégale','La coopération régionale facilite les échanges'],exercises:[
    Exercise(id:'core_hg_3e_de1',lessonId:'core_hg_3e_development',question:'Quel indicateur contribue à mesurer le développement humain ?',options:['L’accès à l’éducation et à la santé','La couleur des maisons','Le nombre de nuages'],correctIndex:0,explanation:'L’éducation et la santé sont des dimensions importantes du développement humain.'),
    Exercise(id:'core_hg_3e_de2',lessonId:'core_hg_3e_development',question:'Quel est un objectif de la coopération régionale ?',options:['Faciliter les échanges et coordonner des actions','Fermer tous les échanges','Supprimer les services publics'],correctIndex:0,explanation:'La coopération aide les pays à agir sur des enjeux communs.'),
    Exercise(id:'core_hg_3e_de3',lessonId:'core_hg_3e_development',question:'Une étude géographique du développement relie…',options:['Ressources, population, activités et contraintes','Seulement les noms des villes','Uniquement les couleurs d’une carte'],correctIndex:0,explanation:'Le développement dépend de plusieurs facteurs géographiques et humains.'),
  ]),
  AnnualHistoryCivicsUnit(level:SchoolLevel.troisieme,code:'3e',domain:'ecm',unitOrder:1,title:'Démocratie et élections',lessonId:'core_ecm_3e_democracy',lessonTitle:'Comprendre les principes démocratiques',summary:'Identifier les principes d’une démocratie et les conditions d’élections équitables.',content:'La démocratie repose sur la participation des citoyens, le pluralisme, les libertés, l’État de droit et la responsabilité des dirigeants. Une élection équitable nécessite des règles connues, la liberté de choix, un vote secret, un dépouillement transparent et la possibilité de contester selon la loi. Le citoyen s’informe, respecte les opinions différentes et refuse la violence et la corruption.',keyPoints:['Participation, libertés et pluralisme','Vote secret et dépouillement transparent','Respect des règles et refus de la violence'],exercises:[
    Exercise(id:'core_ecm_3e_dm1',lessonId:'core_ecm_3e_democracy',question:'Quel principe protège le choix de l’électeur ?',options:['Le vote secret','La menace','La falsification'],correctIndex:0,explanation:'Le vote secret protège la liberté de choix.'),
    Exercise(id:'core_ecm_3e_dm2',lessonId:'core_ecm_3e_democracy',question:'Quel comportement est démocratique ?',options:['Respecter les opinions différentes','Interdire toute opposition','Imposer son avis par la violence'],correctIndex:0,explanation:'Le pluralisme et le respect des opinions sont essentiels à la démocratie.'),
    Exercise(id:'core_ecm_3e_dm3',lessonId:'core_ecm_3e_democracy',question:'Que faire en cas de contestation électorale ?',options:['Utiliser les procédures prévues par la loi','Recourir à la violence','Détruire les urnes'],correctIndex:0,explanation:'Les contestations doivent suivre les voies légales.'),
  ]),
  AnnualHistoryCivicsUnit(level:SchoolLevel.troisieme,code:'3e',domain:'ecm',unitOrder:2,title:'Paix, tolérance et lutte contre la corruption',lessonId:'core_ecm_3e_peace',lessonTitle:'Agir pour la paix et l’intégrité',summary:'Développer des comportements de paix, de tolérance et d’intégrité.',content:'La paix ne signifie pas seulement l’absence de guerre : elle suppose le respect des droits, la justice, le dialogue et la sécurité. La tolérance consiste à respecter les différences sans accepter les violences ou les discriminations. La corruption est l’utilisation abusive d’une fonction ou d’un pouvoir pour obtenir un avantage personnel. Pour la prévenir, on encourage la transparence, la responsabilité, le refus des cadeaux illicites et le signalement par des voies sûres.',keyPoints:['La paix se construit par le dialogue et la justice','Tolérance : respect des différences et refus de discrimination','Intégrité : transparence et refus des avantages illicites'],exercises:[
    Exercise(id:'core_ecm_3e_p1',lessonId:'core_ecm_3e_peace',question:'Quelle action favorise la paix ?',options:['Écouter et rechercher une solution équitable','Humilier un adversaire','Propager une rumeur'],correctIndex:0,explanation:'Le dialogue et la recherche d’une solution équitable favorisent la paix.'),
    Exercise(id:'core_ecm_3e_p2',lessonId:'core_ecm_3e_peace',question:'La corruption consiste notamment à…',options:['Utiliser abusivement un pouvoir pour un avantage personnel','Respecter les règles','Rendre compte de son travail'],correctIndex:0,explanation:'La corruption est l’usage abusif d’une fonction à des fins personnelles.'),
    Exercise(id:'core_ecm_3e_p3',lessonId:'core_ecm_3e_peace',question:'Quel comportement montre l’intégrité ?',options:['Refuser un avantage illicite','Falsifier un document','Favoriser un proche illégalement'],correctIndex:0,explanation:'L’intégrité implique honnêteté et refus des avantages illicites.'),
  ]),

];

